import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = []
    for i in range(n):
        a.append(int(input_data[i+1]))

    total_ops = 0
    for x in a:
        count = 0
        while x % 2 == 0:
            count += 1
            x //= 2
        total_ops += count

    print(total_ops)

if __name__ == "__main__":
    solve()
